import math

def solve_quadratic(A, B, C):
    """Solve the quadratic equation Ax^2 + Bx + C = 0"""
    if A == 0:
        # Linear equation Bx + C = 0
        if B == 0:
            if C == 0:
                return -1  # Infinite roots
            else:
                return 0   # No solution
        else:
            # One root
            root = -C / B
            return 1, [root]
    else:
        # Quadratic equation
        discriminant = B**2 - 4 * A * C
        if discriminant < 0:
            return 0
        elif discriminant == 0:
            root = -B / (2 * A)
            return 1, [root]
        else:
            sqrt_d = math.sqrt(discriminant)
            root1 = (-B - sqrt_d) / (2 * A)
            root2 = (-B + sqrt_d) / (2 * A)
            # Ensure ascending order
            if root1 > root2:
                root1, root2 = root2, root1
            return 2, [root1, root2]

def format_output(result):
    """Format the output according to the problem requirements"""
    if result == -1:
        print(-1)
    elif result == 0:
        print(0)
    else:
        print(result)
        for root in result[1]:
            print(f"{root:.10f}")

# Read input
A, B, C = map(int, input().split())

# Solve and output
result = solve_quadratic(A, B, C)
format_output(result)
