def count_ways(s, t):
    MOD = 10**9 + 7
    n = len(s)
    m = len(t)

    # Find all occurrences of t in s
    occurrences = []
    for i in range(n - m + 1):
        if s[i:i+m] == t:
            occurrences.append(i)

    # If no occurrences, return 0
    if not occurrences:
        return 0

    # Count valid substrings containing each occurrence
    valid_substrings = []
    for start in occurrences:
        # Count substrings starting at or before start and ending at or after start + m - 1
        count = 0
        for i in range(start + 1):
            for j in range(start + m, n + 1):
                if s[i:j] == t:
                    count += 1
        valid_substrings.append(count)

    # Now we need to count ways to choose k non-overlapping substrings from these
    # This is similar to the problem of counting ways to partition a string with k non-overlapping substrings

    # Let dp[i][j] be the number of ways to partition the first i characters of s using j substrings
    dp = [[0] * (len(occurrences) + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(len(occurrences) + 1):
            if j > 0:
                # Try to extend the last substring
                for k in range(len(occurrences)):
                    if occurrences[k] + m <= i:
                        dp[i][j] = (dp[i][j] + dp[occurrences[k] + m][j - 1]) % MOD

    # Sum all ways for k >= 1
    result = sum(dp[n][j] for j in range(1, len(occurrences) + 1)) % MOD
    return result

# Read input
s = input().strip()
t = input().strip()

# Calculate and print result
print(count_ways(s, t))
