def bfs(a1, b1, a2, b2):
    """Breadth-first search to find minimum operations to make areas equal"""
    from collections import deque

    # Initial state: (a1, b1, a2, b2, operations)
    queue = deque([(a1, b1, a2, b2, 0)])
    visited = set()

    while queue:
        a, b, c, d, ops = queue.popleft()

        # Check if areas are equal
        if a * b == c * d:
            return ops, a, b, c, d

        # Check if we've visited this state
        if (a, b, c, d) in visited:
            continue
        visited.add((a, b, c, d))

        # Try all operations on both bars
        for bar1 in [(a, b), (c, d)]:
            for bar2 in [(a, b), (c, d)]:
                if bar1 == bar2:
                    continue

                # Apply operations to bar1
                for new_a, new_b in get_next_states(bar1[0], bar1[1]):
                    if new_a == bar1[0] and new_b == bar1[1]:
