import sys

def count_consecutive(sequence, k):
    """Count the number of ways to choose k consecutive elements from a sequence."""
    count = 0
    current_length = 0

    for char in sequence:
        if char == '.':
            current_length += 1
        else:
            current_length = 0

        if current_length >= k:
            count += 1

    return count

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    k = int(data[2])

    # Read the matrix
    matrix = []
    index = 3
    for i in range(n):
        row = data[index:index+m]
        matrix.append(row)
        index += m

    # Count ways in rows
    row_count = 0
    for row in matrix:
        current_length = 0
        for char in row:
            if char == '.':
                current_length += 1
            else:
                current_length = 0

            if current_length >= k:
                row_count += 1

    # Count ways in columns
    col_count = 0
    for col in range(m):
        current_length = 0
        for row in range(n):
            if matrix[row][col] == '.':
                current_length += 1
            else:
                current_length = 0

            if current_length >= k:
                col_count += 1

    print(row_count + col_count)

if __name__ == "__main__":
    solve()
