from collections import deque

def solve():
    a1, b1 = map(int, input().split())
    a2, b2 = map(int, input().split())

    # BFS to find minimum operations
    queue = deque([(a1, b1, a2, b2, 0)])
    visited = set()
    visited.add((a1, b1, a2, b2))

    while queue:
        a, b, c, d, ops = queue.popleft()

        # Check if areas are equal
        if a * b == c * d:
            print(ops)
            print(f"{a} {b}")
            print(f"{c} {d}")
            return

        # Generate next states
        next_states = []

        # Apply operations to first bar
        if a % 2 == 0:
            next_states.append((a // 2, b, c, d, ops + 1))
        if b % 2 == 0:
            next_states.append((a, b // 2, c, d, ops + 1))
        if a % 3 == 0:
            next_states.append((a // 3, b, c, d, ops + 1))
        if b % 3 == 0:
            next_states.append((a, b // 3, c, d, ops + 1))

        # Apply operations to second bar
        if c % 2 == 0:
            next_states.append((a, b, c // 2, d, ops + 1))
        if d % 2 == 0:
            next_states.append((a, b, c, d // 2, ops + 1))
        if c % 3 == 0:
            next_states.append((a, b, c // 3, d, ops + 1))
        if d % 3 == 0:
            next_states.append((a, b, c, d // 3, ops + 1))

        # Add new states to queue
        for state in next_states:
            if state not in visited:
                visited.add(state)
                queue.append(state)

    # No solution found
    print(-1)

