import sys
import math

def readints():
    return list(map(int, sys.stdin.readline().split()))

def convex_hull(points):
    """Returns the convex hull of a set of points.
    Returns the points in counter-clockwise order around the hull.
    """
    points = sorted(set(points))
    if len(points) <= 1:
        return points

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in points:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(points):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    return lower[:-1] + upper[:-1]

def is_congruent(hull1, hull2):
    """Check if two convex hulls can be made congruent by rotation and translation.
    """
    # Check if both hulls have the same number of points
    if len(hull1) != len(hull2):
        return False

    # Check if the relative distances between points are the same
    def dist(p1, p2):
        return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

    # Find the point with the minimum distance to the origin (pivot point)
    def find_pivot(hull):
        return min(hull, key=lambda p: math.hypot(p[0], p[1]))

    # Rotate hull so that the pivot point is at the origin
    def rotate_to_origin(hull):
        pivot = find_pivot(hull)
        return [(x - pivot[0], y - pivot[1]) for x, y in hull]

    # Check if the distances from the pivot are the same
    def check_distances(hull):
        pivot = find_pivot(hull)
        dists = sorted([math.hypot(x - pivot[0], y - pivot[1]) for x, y in hull])
        return dists

    # Check if the relative angles between points are the same
    def check_angles(hull):
        pivot = find_pivot(hull)
        angles = sorted([math.atan2(y - pivot[1], x - pivot[0]) for x, y in hull])
        return angles

    # Check if distances are the same
    if check_distances(hull1) != check_distances(hull2):
        return False

    # Check if angles are the same
    return check_angles(hull1) == check_angles(hull2)

def solve():
    n, m = readints()
    engine1 = [tuple(readints()) for _ in range(n)]
    engine2 = [tuple(readints()) for _ in range(m)]

    hull1 = convex_hull(engine1)
    hull2 = convex_hull(engine2)

