import sys
import heapq

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        a = int(data[idx+1])
        b = int(data[idx+2])
        idx += 3

        # Special cases
        if a == 1:
            # Can only add b repeatedly
            if (n - 1) % b == 0:
                print("Yes")
            else:
                print("No")
            continue

        if b == 0:
            # Can only multiply by a repeatedly
            if n == 1 or (n % a == 0 and n // a >= 1):
                print("Yes")
            else:
                print("No")
            continue

        # General case using Dijkstra's algorithm
        visited = set()
        heap = [(1, 0)]  # (value, operations)

        while heap:
            val, _ = heapq.heappop(heap)

            if val == n:
                print("Yes")
                break

            if val > n:
                continue

            if val in visited:
                continue

            visited.add(val)

            # Add b
            if val + b <= n and val + b not in visited:
                heapq.heappush(heap, (val + b, 0))

            # Multiply by a
            if val * a <= n and val * a not in visited:
                heapq.heappush(heap, (val * a, 0))
        else:
            print("No")

if __name__ == "__main__":
    solve()
