import sys

def has_common_digit(a, b):
    """Check if a and b have at least one common digit"""
    digits_a = set(str(a))
    digits_b = set(str(b))
    return len(digits_a & digits_b) > 0

def count_common_digit_divisors(x):
    """Count divisors of x that share at least one digit with x"""
    count = 0

    # Check all potential divisors up to sqrt(x)
    for i in range(1, int(x**0.5) + 1):
        if x % i == 0:
            # i is a divisor
            if has_common_digit(x, i):
                count += 1

            # x // i is also a divisor
            if i != x // i and has_common_digit(x, x // i):
                count += 1

    return count

if __name__ == "__main__":
    x = int(sys.stdin.readline())
    print(count_common_digit_divisors(x))
