import sys

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    a = [int(next(it)) for _ in range(n)]
    b = [int(next(it)) for _ in range(m)]

    max_b = max(b)
    min_b = min(b)

    def score(k):
        # remove a[k], compute max product
        # remaining: for ai in a without a[k]
        max_prod = float('-inf')
        for i in range(n):
            if i == k:
                continue
            ai = a[i]
            if ai > 0:
                prod = ai * max_b
            elif ai < 0:
                prod = ai * min_b
            else:
                prod = 0
            if prod > max_prod:
