    for _ in range(t):
        n, q = map(int, input().split())
        a = list(map(int, input().split()))

        # Calculate maximum strength for the initial array
        max_strength = 0
        # Try all possible subsequences

        # Brute force approach for small n (n <= 3)
        for mask in range(1, 1 << n):
            subset = []
            for i in range(n):
                if mask & (1 << i):
                    subset.append(a[i])

            # Calculate strength for this subsequence
            strength = 0
            for i, val in enumerate(subset):
                if i % 2 == 0:
                    strength += val
                else:
                    strength -= val

            max_strength = max(max_strength, strength)

        results.append(str(max_strength))

        # Process swaps
        for _ in range(q):
            l, r = map(int, input().split())
            l -= 1
