    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    results = []

    for _ in range(t):
        n = int(data[idx])
        a = int(data[idx+1])
        b = int(data[idx+2])
        idx += 3

        if a == 1:
            # We can only add b repeatedly
            if (n - 1) % b == 0:
                results.append("Yes")
            else:
                results.append("No")
        else:
            # Try to find k such that n - a^k is divisible by b
            # We need to check for small k values only, since a^k grows quickly
            found = False
            for k in range(32):  # 2^32 is a large number, so we only need up to 32 multiplications
                power = a ** k
                if power > n:
                    break
                if (n - power) % b == 0:
                    found = True
                    break
            results.append("Yes" if found else "No")

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
