        graph[i].append(x)
        graph[i].append(y)

    # Maximum matching in bipartite graph between guests (0-indexed) and snacks (0-indexed)
    max_matching = hopcroft_karp(graph, k, n)

    # Minimum number of sad guests = total guests - maximum matching
    print(k - max_matching)

if __name__ == "__main__":
