    for a in range(1, int((2 * x) ** 0.5) + 1):
        # Calculate the constant term
        const = a * (a + 1) * (2 * a + 1)

        # Check if (6x - const) is divisible by 3a(a+1)
        numerator = 6 * x - const
        if numerator <= 0:
            continue

        if numerator % (3 * a * (a + 1)) != 0:
            continue

        c = numerator // (3 * a * (a + 1))
        b = a - 1 + c

        # Check if b is valid (should be >= a)
        if b < a:
            continue

        # Add both (a, b) and (b, a) if they are distinct
        if a != b:
            results.append((a, b))
            results.append((b, a))
        else:
            results.append((a, b))

