    n = int(input())
    players = []

    for _ in range(n):
        name, points = input().split()
        points = int(points)
        players.append((name, points))

    # Sort players by best result (descending)
    players.sort(key=lambda x: x[1], reverse=True)

    # Calculate best results for each player
    best_results = [p[1] for p in players]

    # For each player, count how many have strictly better results
    results = []
    for i, (name, points) in enumerate(players):
        # Count how many players have better results
        better_count = sum(1 for j, (other_name, other_points) in enumerate(players) \
                          if j != i and other_points > points)

        # Calculate percentile
        percentile = (n - better_count - 1) / n * 100

        # Determine category
        category = determine_category(percentile)
        results.append((name, category))

    # Remove duplicates (keep the first occurrence)
    unique_results = {}
    for name, category in results:
        if name not in unique_results:
            unique_results[name] = category

    # Output
    print(len(unique_results))
    for name, category in unique_results.items():
