import sys

def count_consecutive(sequence, k):
    """Count the number of ways to choose k consecutive seats from a sequence."""
    count = 0
    current_length = 0

    for char in sequence:
        if char == '.':
            current_length += 1
        else:
            if current_length > 0:
                # Add ways for this sequence
                count += max(0, current_length - k + 1)
            current_length = 0

    # Check the last sequence
    if current_length > 0:
        count += max(0, current_length - k + 1)

    return count

def solve():
