        # Split into (2n - qi) parts, each of size 2 * qi
        parts = []
        for j in range(2 * n - qi):
            start = j * (2 * qi)
            end = start + (2 * qi)
            part = arr[start:end]
            parts.append(part)

        # Reverse each part
        for i in range(len(parts)):
            parts[i] = parts[i][::-1]

        # Join back
        arr = [num for part in parts for num in part]

        # Count inversions
        print(count_inversions(arr))

