def find_mst_weight(n, p, a):
    # Group consecutive equal values
    groups = []
    current_value = a[0]
    current_length = 1

    for i in range(1, n):
        if a[i] == current_value:
            current_length += 1
        else:
            groups.append((current_value, current_length))
            current_value = a[i]
            current_length = 1
    groups.append((current_value, current_length))

    # Kruskal's algorithm
    parent = list(range(n))
    rank = [1] * n

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu == pv:
            return False
        if rank[pu] < rank[pv]:
            parent[pu] = pv
        elif rank[pu] > rank[pv]:
            parent[pv] = pu
        else:
            parent[pv] = pu
            rank[pu] += 1
        return True

    total_weight = 0

    # Connect within each group
    for value, length in groups:
        # Connect all vertices in this group with each other
        # We can use the smallest vertex as the hub
        hub = n - length  # Last vertex of this group
        for i in range(n - length, n - length + length):
            if i != hub:
                if union(i, hub):
                    total_weight += value

    # Connect between consecutive groups
    for i in range(len(groups) - 1):
        # Connect the last vertex of group i with the first vertex of group i+1
        # using the edge weight p
        if union(n - length_of_group[i], n - length_of_group[i] + length_of_group[i]):
            total_weight += p

    return total_weight

