import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    T = int(next(it))

    # Build graph
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        t = int(next(it))
        graph[u].append((v, t))

    # Topological sort
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v, _ in graph[u]:
            in_degree[v] += 1

    # Kahn's algorithm for topological sort
    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
    topo_order = []
    while queue:
        u = queue.pop(0)
        topo_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[v][k] = minimum time to reach v with k nodes visited
    INF = float('inf')
    dp = [[INF] * (n + 1) for _ in range(n + 1)]
    dp[1][1] = 0  # Start at node 1 with 1 node visited and 0 time

    for v in topo_order:
        for k in range(1, n + 1):
            if dp[v][k] == INF:
                continue
            # Try all outgoing edges
            for u, t in graph[v]:
                if dp[v][k] + t <= T:
                    if dp[u][k + 1] > dp[v][k] + t:
                        dp[u][k + 1] = dp[v][k] + t

    # Find maximum k such that dp[n][k] <= T
    max_k = 1
    for k in range(2, n + 1):
        if dp[n][k] <= T:
            max_k = k

    # Reconstruct path
    path = []
    current = n
    for k in range(max_k, 0, -1):
        # Find which node leads to current with k nodes
        for prev in range(1, n + 1):
            if prev == current:
                continue
            for _, t in graph[prev]:
                if dp[current][k] == dp[prev][k - 1] + t:
                    path.append(current)
                    current = prev
                    break
            if current != n:
                break

    path.append(n)
    path.reverse()

    print(max_k)
    print(' '.join(map(str, path)))

if __name__ == '__main__':
    solve()
