import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    T = int(next(it))

    # Build graph
    graph = [[] for _ in range(n + 1)]
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        t = int(next(it))
        graph[u].append((v, t))

    # Topological sort using Kahn's algorithm
    in_degree = [0] * (n + 1)
    for u in range(1, n + 1):
        for v, _ in graph[u]:
            in_degree[v] += 1

    queue = [i for i in range(1, n + 1) if in_degree[i] == 0]
    topo_order = []
    while queue:
        u = queue.pop(0)
        topo_order.append(u)
        for v, _ in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[k][v] = minimum time to reach v with exactly k nodes visited
    INF = float('inf')
    dp = [[INF] * (n + 1) for _ in range(n + 1)]
    dp[1][1] = 0  # Start at node 1 with 1 node visited and 0 time

    for u in topo_order:
        for v, t in graph[u]:
            for k in range(1, n + 1):
                if dp[k][u] != INF:
                    new_time = dp[k][u] + t
                    if new_time < dp[k + 1][v]:
                        dp[k + 1][v] = new_time

    # Find maximum k such that dp[k][n] <= T
    max_k = 1
    for k in range(2, n + 1):
        if dp[k][n] <= T:
            max_k = k

    # Reconstruct path
    path = []
    current = n
    for k in range(max_k, 0, -1):
        for v in range(1, n + 1):
            if dp[k][v] <= T and dp[k][v] == dp[k - 1][current] + (time from node with k-1 nodes to current):
                path.append(v)
                current = v
                break

    path.reverse()

    print(max_k)
    print(' '.join(map(str, path)))

if __name__ == '__main__':
    solve()
