{"code": "
def solve():
    n = int(input())
    s = input().strip()

    # Target patterns: alternating colors
    target1 = [1 if i % 2 == 0 else 0 for i in range(n)]  # 101010...
    target2 = [0 if i % 2 == 0 else 1 for i in range(n)]  # 010101...

    def calculate_moves(target):
        # Count how many positions need to be changed
        changes = 0
        for i in range(n):
            if s[i] != str(target[i]):
                changes += 1

        # If changes is odd, it's impossible
        if changes % 2 != 0:
            return float('inf')

        # Group consecutive positions needing change
        groups = []
        i = 0
        while i < n:
            if s[i] != str(target[i]):
                # Start of a group
                start = i
                while i < n and s[i] != str(target[i]):
                    i += 1
                groups.append((start, i-1))
            else:
                i += 1

        # Calculate moves for each group
        moves = 0
        for start, end in groups:
            # For a block of length k, we need ceil(k/2) moves
            k = end - start + 1
            moves += (k + 1) // 2

        return moves

    min_moves = min(calculate_moves(target1), calculate_moves(target2))
    print(min_moves if min_moves != float('inf') else -1)

solve()
