import sys
from collections import deque, defaultdict

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    r = int(data[0])
    c = int(data[1])
    grid = []
    idx = 2

    for i in range(r):
        row = data[idx:idx+c]
        grid.append(row)
        idx += c

    # Find start and exit positions
    start = None
    exit_pos = None
    breeders = defaultdict(int)

    for i in range(r):
        for j in range(c):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'E':
                exit_pos = (i, j)
            elif grid[i][j].isdigit():
                breeders[(i, j)] = int(grid[i][j])

    # BFS to find shortest path from start to exit
    visited = [[False] * c for _ in range(r)]
    queue = deque([(start[0], start[1], 0, 0)])  # (row, col, moves, battles)
    visited[start[0]][start[1]] = True

    min_battles = float('inf')

    while queue:
        i, j, moves, battles = queue.popleft()

        # Check if we reached the exit
        if (i, j) == exit_pos:
            min_battles = min(min_battles, battles)
            continue

        # Try all four directions
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj

            # Check if new position is valid
            if 0 <= ni < r and 0 <= nj < c:
                if grid[ni][nj] == 'T':
                    continue  # Can't move into a tree

                # Calculate number of breeders who can reach this cell in 'moves + 1' moves
                breeder_count = 0
                for (bi, bj), count in breeders.items():
                    if abs(bi - ni) + abs(bj - nj) == moves + 1:
                        breeder_count += count

                # Check if we've visited this cell with this number of moves
                if not visited[ni][nj] or visited[ni][nj] and moves + 1 <= visited[ni][nj]:
                    visited[ni][nj] = moves + 1
                    queue.append((ni, nj, moves + 1, battles + breeder_count))

    print(min_battles)

