import sys

def has_common_digit(a, b):
    """Check if a and b have at least one common digit"""
    str_a = str(a)
    str_b = str(b)
    return any(char in str_b for char in str_a)

def get_divisors(x):
    """Get all divisors of x"""
    divisors = set()
    for i in range(1, int(x**0.5) + 1):
        if x % i == 0:
            divisors.add(i)
            divisors.add(x // i)
