def find_valid_partitions(s):
    """Find all valid partitions of s into segments of length 2 or 3, no consecutive duplicates."""
    n = len(s)

    # Memoization cache
    cache = {}

    def can_partition(start, last_segment):
        """Check if we can partition from start to end, given last_segment."""
        if start == n:
            return True

        if (start, last_segment) in cache:
            return cache[(start, last_segment)]

        # Try taking a segment of length 2
        if start + 2 <= n:
            segment = s[start:start+2]
            if segment != last_segment:
                if can_partition(start + 2, segment):
                    cache[(start, last_segment)] = True
                    return True

        # Try taking a segment of length 3
        if start + 3 <= n:
            segment = s[start:start+3]
            if segment != last_segment:
                if can_partition(start + 3, segment):
                    cache[(start, last_segment)] = True
                    return True

        cache[(start, last_segment)] = False
        return False

    # Try all possible starting segments
    results = set()

    # Try starting with a segment of length 2
    if n >= 2:
        for i in range(n - 1):
            segment = s[i:i+2]
            if can_partition(i + 2, segment):
                results.add(segment)

    # Try starting with a segment of length 3
    if n >= 3:
        for i in range(n - 2):
            segment = s[i:i+3]
            if can_partition(i + 3, segment):
                results.add(segment)

    return results

def solve():
    s = input().strip()
    n = len(s)

    # Set of all valid suffixes
    valid_suffixes = set()

    # Try all possible root lengths
    for r in range(5, n - 1):  # r from 5 to n-2 inclusive
        suffix_part = s[r:]  # suffix part after root

        # Find all valid partitions of suffix_part
        partitions = find_valid_partitions(suffix_part)

        # Add all suffix strings from these partitions
        for partition in partitions:
            valid_suffixes.add(partition)

    # Output results
    print(len(valid_suffixes))
    for suffix in sorted(valid_suffixes):
        print(suffix)

solve()
