def is_centrosymmetric(polygon, n):
    # Calculate midpoint
    mid_x = sum(x for x, y in polygon) / n
    mid_y = sum(y for x, y in polygon) / n

    # Check if for every vertex, the opposite vertex exists
    for i in range(n):
