        x2, y2 = polygon[(i + n // 2) % n]

        # Check if (x2, y2) is the opposite of (x1, y1) about the midpoint
        # Opposite point should be (2*mid_x - x1, 2*mid_y - y1)
        if not (abs(x2 - (2 * mid_x - x1)) < 1e-9 and abs(y2 - (2 * mid_y - y1)) < 1e-9):
