    visited = [False] * (n + 1)
    order = []

    def dfs1(u):
        visited[u] = True
        for v in graph[u]:
            if not visited[v]:
                dfs1(v)
        order.append(u)

    for u in range(1, n + 1):
        if not visited[u]:
            dfs1(u)

    # Transpose graph
    transpose = defaultdict(list)
    for u in range(1, n + 1):
        for v in graph[u]:
            transpose[v].append(u)

    visited = [False] * (n + 1)
    scc = []

    def dfs2(u, component):
        visited[u] = True
        component.append(u)
        for v in transpose[u]:
            if not visited[v]:
                dfs2(v, component)

    for u in reversed(order):
        if not visited[u]:
            component = []
            dfs2(u, component)
            scc.append(component)

