def is_convex(grid, n, m):
    black_cells = [(i, j) for i in range(n) for j in range(m) if grid[i][j] == 'B']

    # Check if we can reach any black cell from any other black cell with at most one turn
    for i1, j1 in black_cells:
        for i2, j2 in black_cells:
            # Check if there's a black cell that acts as a turning point
            found = False

            # Check if there's a black cell in the same row as both
            for y in range(min(j1, j2), max(j1, j2) + 1):
                if grid[i1][y] == 'B':
                    # We can go from (i1,j1) to (i1,y) horizontally, then from (i1,y) to (i2,y) vertically
                    if all(grid[i][y] == 'B' for i in range(min(i1, i2), max(i1, i2) + 1)):
                        found = True
                        break

            if not found:
                # Check if there's a black cell in the same column as both
                for x in range(min(i1, i2), max(i1, i2) + 1):
