import math

def distance(p1, p2):
    return math.hypot(p1[0] - p2[0], p1[1] - p2[1])

def is_square(points):
    # Calculate all pairwise distances
    dists = []
    for i in range(4):
        for j in range(i + 1, 4):
            dists.append(distance(points[i], points[j]))

    # Count occurrences of each distance
    dist_count = {}
    for d in dists:
        dist_count[d] = dist_count.get(d, 0) + 1

    # Check if we have 4 sides and 2 diagonals
    sides = []
    diagonals = []
    for d, count in dist_count.items():
        if count == 4:
            sides.append(d)
        elif count == 2:
            diagonals.append(d)

    # There should be 1 side length and 1 diagonal length
    if len(sides) == 1 and len(diagonals) == 1:
        side = sides[0]
        diagonal = diagonals[0]
        # Check if diagonal is sqrt(2) times side
        return math.isclose(diagonal, side * math.sqrt(2))
    return False

def is_rectangle(points):
    # Calculate all pairwise distances
    dists = []
    for i in range(4):
        for j in range(i + 1, 4):
            dists.append(distance(points[i], points[j]))

    # Count occurrences of each distance
    dist_count = {}
    for d in dists:
        dist_count[d] = dist_count.get(d, 0) + 1

    # Check if we have 2 pairs of sides and 2 diagonals
    sides = []
    diagonals = []
    for d, count in dist_count.items():
        if count == 4:
            sides.append(d)
        elif count == 2:
            diagonals.append(d)

    # There should be 2 side lengths and 1 diagonal length
    if len(sides) == 2 and len(diagonals) == 1:
        side1, side2 = sides
        diagonal = diagonals[0]
        # Check if diagonal is sqrt(side1^2 + side2^2)
        return math.isclose(diagonal, math.sqrt(side1**2 + side2**2))
    return False

def solve():
    points = []
    for i in range(8):
        x, y = map(int, input().split())
        points.append((x, y))

    # Try all possible partitions into two sets of 4
    from itertools import combinations

    for square_indices in combinations(range(8), 4):
        square_points = [points[i] for i in square_indices]
        rectangle_indices = [i for i in range(8) if i not in square_indices]
        rectangle_points = [points[i] for i in rectangle_indices]

        if is_square(square_points) and is_rectangle(rectangle_points):
            # Found a valid partition
            square_indices = sorted(square_indices)
            rectangle_indices = sorted(rectangle_indices)
            print("YES")
            print(' '.join(map(str, [i + 1 for i in square_indices])))
            print(' '.join(map(str, [i + 1 for i in rectangle_indices])))
            return

    print("NO")

