import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        a = int(data[idx+1])
        b = int(data[idx+2])
        idx += 3

        # Special cases
        if n == 1:
            print("Yes")
            continue
        if a == 1 and b == 1:
            print("Yes")
            continue
        if a == 1:
            # Only can add b, so check if (n-1) % b == 0
            if (n - 1) % b == 0:
                print("Yes")
            else:
                print("No")
            continue
        if b == 1:
            # Only can multiply by a, so check if n % a == 0 and n/a is reachable
            if n % a == 0:
                print("Yes")
            else:
                print("No")
            continue

        # BFS from n backwards with priority on subtracting b
        visited = set()
        queue = deque([(n, 0)])  # (value, operations)
        visited.add(n)

        found = False
        while queue:
            x, ops = queue.popleft()

            # Check if we can reach 1 from x
            if x == 1:
                found = True
                break

            # Try dividing by a (reverse of multiply)
            if x % a == 0:
                y = x // a
                if y not in visited:
                    visited.add(y)
                    queue.append((y, ops + 1))

            # Try subtracting b (reverse of add)
            if x - b > 0 and (x - b) not in visited:
                visited.add(x - b)
                queue.append((x - b, ops + 1))

        print("Yes" if found else "No")

if __name__ == "__main__":
    solve()
