import sys
from collections import defaultdict, deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    m = int(next(it))
    T = int(next(it))

    # Build adjacency list
    adj = defaultdict(list)
    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        t = int(next(it))
        adj[u].append((v, t))

    # Topological sort using Kahn's algorithm
    in_degree = [0] * (n + 1)
    for u in adj:
        for v, _ in adj[u]:
            in_degree[v] += 1

    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    top_order = []
    while queue:
        u = queue.popleft()
        top_order.append(u)
        for v, _ in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)

    # DP: dp[u][k] = minimum time to reach u with k visited nodes
    INF = float('inf')
    dp = [[INF] * (n + 1) for _ in range(n + 1)]
    dp[1][1] = 0  # Start at node 1, visited 1 node, time 0

    for u in top_order:
        for k in range(1, n + 1):
            if dp[u][k] == INF:
                continue
            for v, t in adj[u]:
                if dp[v][k + 1] > dp[u][k] + t:
                    dp[v][k + 1] = dp[u][k] + t

    # Find maximum k such that dp[n][k] <= T
    max_k = 1
    for k in range(2, n + 1):
        if dp[n][k] <= T:
            max_k = k

    # Reconstruct path
    path = []
    current = n
    k = max_k

    # Find the predecessor
    for v, t in adj[current]:
        if dp[current][k] == dp[v][k - 1] + t:
            prev = v
            break

    # Trace back from predecessor
    while current != 1:
        path.append(current)
        for v, t in adj[current]:
            if dp[current][k] == dp[v][k - 1] + t:
                current = v
                k -= 1
                break

    path.append(1)
    path.reverse()

    print(max_k)
    print(' '.join(map(str, path)))

