        sorted_vals = sorted((val, idx) for idx, val in enumerate(a))

        # For the optimal subsequence, we take largest, smallest, second largest, second smallest, etc.
        # We need to consider all possible lengths of subsequences

        # Initialize max strength
        max_strength = max(a)

        # Try subsequences of length 2
        for i in range(n):
            for j in range(i + 1, n):
                strength = a[i] - a[j]
                if strength > max_strength:
                    max_strength = strength

        # Try subsequences of length 3
        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    strength = a[i] - a[j] + a[k]
                    if strength > max_strength:
