        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    for l in range(k + 1, n):
                        strength = a[i] - a[j] + a[k] - a[l]
                        if strength > max_strength:
                            max_strength = strength

        # And so on... this is inefficient

        # Actually, a better approach:
        # We can take the largest value, then the smallest, then the second largest, etc.
        # This gives us the optimal alternating sum

        # Sort values and keep track of positions
        sorted_vals = sorted((val, idx) for idx, val in enumerate(a))

