import heapq

def solve():
    r, c = map(int, input().split())
    grid = []
    start = None
    exit = None
    breeders = {}

    for i in range(r):
        row = list(input().strip())
        grid.append(row)
        for j in range(c):
            if row[j] == 'S':
                start = (i, j)
            elif row[j] == 'E':
                exit = (i, j)
            elif row[j].isdigit():
                breeders[(i, j)] = int(row[j])

    # Dijkstra's algorithm
    dist = [[float('inf')] * c for _ in range(r)]
    dist[start[0]][start[1]] = 0

    # (moves, row, col)
    pq = [(0, start[0], start[1])]

    while pq:
        d, i, j = heapq.heappop(pq)

        # If we've already found a better path, skip
        if d > dist[i][j]:
            continue

        # If we reached the exit, we're done
        if (i, j) == exit:
            break

        # Try all four directions
        for di, dj in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            ni, nj = i + di, j + dj

            # Check if the new position is valid
            if 0 <= ni < r and 0 <= nj < c:
                if grid[ni][nj] == 'T':
                    continue  # Can't move into a tree

                # Calculate the new distance
                new_d = d + 1

                # Calculate the cost: sum of breeders that can reach this cell in <= new_d moves
                cost = 0
                for (bi, bj), b_count in breeders.items():
                    # Manhattan distance from breeder's start to our current position
                    if abs(bi - ni) + abs(bj - nj) <= new_d:
                        cost += b_count

                # If this path is better, update
                if dist[ni][nj] > cost:
                    dist[ni][nj] = cost
                    heapq.heappush(pq, (cost, ni, nj))

    print(dist[exit[0]][exit[1]])

solve()
